package dev.aivillages.providers;
import java.util.*;
import org.junit.jupiter.api.Test;
import dev.aivillages.core.kernel.*;
import static dev.aivillages.core.kernel.Contracts.*;
import static dev.aivillages.core.kernel.GatewayPrimitives.Operation;
import static org.junit.jupiter.api.Assertions.*;
final class PlacementGenerationTest {
    static Generation.Request request(){var old=GenerationChecks.request(Generation.Role.INITIAL,"exact approved table placement");var args=new HashMap<String,Value>(old.bound().request().arguments());var box=((ContainerValue)args.remove("destination")).value();args.put("source",new ContainerValue(box));args.put("target",new FacilityValue(new FacilityRef(box.dimension(),box.x(),box.y(),box.z())));args.put("amount",new IntValue(1));var bound=new ValidatedRequest(new CapabilityRequest(CraftingTablePlacement.ID,args),old.bound().context(),old.bound().observation());return new Generation.Request(old.id(),bound,CraftingTablePlacement.SPEC,CraftingTablePlacement.operations().stream().map(Operation::signature).toList(),List.of(),old.role(),old.context());}
    static String proposal(boolean valid){return StrictJson.canonical(Map.of("schema",1,"capability",CraftingTablePlacement.ID.name(),"capabilityVersion",1,"dependencies",List.of(),"body",Map.of("preflight",Operation.OBSERVE_TABLE_SITE.signature().id(),"batchSize",1,"cycle",(valid?List.of(Operation.MOVE_TO_INPUT,Operation.WITHDRAW_TABLE_ITEM,Operation.MOVE_TO_PLACEMENT,Operation.PLACE_CRAFTING_TABLE):List.of(Operation.MOVE_TO_INPUT,Operation.OBSERVE_TABLE_SITE,Operation.MOVE_TO_PLACEMENT,Operation.PLACE_CRAFTING_TABLE)).stream().map(op->op.signature().id()).toList(),"result",Map.of("param","amount"))));}
    @Test void actualModelSelectionLowersToLateBoundPlacementAndCompiles()throws Exception{try(var f=new GenerationChecks.Fixture()){var limits=new Budgets.InferenceLimits(new Budgets.Limits(Map.of(Budgets.Kind.CALLS,1L,Budgets.Kind.INPUT_BYTES,16384L,Budgets.Kind.OUTPUT_BYTES,8192L),f.clock.millis()+10000),16384,8192);var h=f.adapter.generate(request(),limits,new Budgets.Ledger(limits.total(),f.clock));var wire=StrictJson.transportObject(f.backend.bodies.getFirst());assertTrue(wire.toString().contains("exact approved site"));f.backend.respond(0,proposal(true),900L,180L);var result=h.result().toCompletableFuture().join();assertEquals(Generation.Outcome.CANDIDATE,result.outcome());var compiled=assertInstanceOf(SkillCompiler.Success.class,new SkillCompiler(PlanningGoals.catalog(),GatewayPrimitives.instance(),ref->Optional.empty()).compile(result.candidateIr()));assertEquals(CraftingTablePlacement.ID,compiled.skill().artifact().descriptor().ref().capability());assertTrue(compiled.skill().artifact().descriptor().dependencies().isEmpty());assertEquals(5,compiled.skill().artifact().descriptor().primitives().size());assertTrue(result.candidateIr().contains("target"));assertFalse(result.candidateIr().contains("destination"));}}
    @Test void modelCannotSmuggleObservationIntoEffectCycle()throws Exception{try(var f=new GenerationChecks.Fixture()){var limits=new Budgets.InferenceLimits(new Budgets.Limits(Map.of(Budgets.Kind.CALLS,1L,Budgets.Kind.INPUT_BYTES,16384L,Budgets.Kind.OUTPUT_BYTES,8192L),f.clock.millis()+10000),16384,8192);var h=f.adapter.generate(request(),limits,new Budgets.Ledger(limits.total(),f.clock));f.backend.respond(0,proposal(false),900L,180L);var result=h.result().toCompletableFuture().join();assertEquals(Generation.Outcome.MALFORMED,result.outcome());assertNull(result.candidateIr());}}
}
